#include <cuda_runtime.h>
#include <cstdio>
int main() {
    int count = 0;
    cudaError_t status = cudaGetDeviceCount(&count);
    if (status != cudaSuccess) {
        std::fprintf(stderr, "CUDA error: %d\n", static_cast<int>(status));
        return 1;
    }
    std::printf("CUDA devices: %d\n", count);
}
